function citationMarkup(text){return escapeHtml(text).replace(/\[cite:([A-Za-z0-9_.:-]+)\]/g,(_,id)=>{const index=Object.keys(state.sources).indexOf(id)+1;return `<button class="cite" data-source="${id}" aria-label="Open source ${index}">${index||'•'}</button>`})}
