function renderEdition(){const e=state.edition;$('#hero-date').textContent=`Edition ${e.id} · ${localTime(e.data_as_of)}`;$('#as-of').textContent=localTime(e.data_as_of,true);$('#source-count').textContent=Object.keys(state.sources).length;const quality=e.quality||{};$('#quality-strip').innerHTML=`<span>CITATION COVERAGE <b>${Math.round((quality.citation_coverage||0)*100)}%</b></span><span>HALLUCINATION RATE <b>${Math.round((quality.hallucination_rate||0)*100)}%</b></span><span>ATTRIBUTION <b>${Math.round((quality.source_attribution_precision||0)*100)}%</b></span>`;const sections=Object.entries(e.sections).filter(([,text])=>text);$('#section-nav').innerHTML=sections.map(([name],i)=>`<a href="#section-${i}">${String(i+1).padStart(2,'0')} ${name}</a>`).join('');$('#brief-content').innerHTML=sections.map(([name,text],i)=>`<section class="brief-section" id="section-${i}"><div><span class="section-number">${String(i+1).padStart(2,'0')} / ${String(sections.length).padStart(2,'0')}</span><h3>${escapeHtml(name)}</h3></div><div class="brief-prose">${humanize(text,name)}</div></section>`).join('');$$('.brief-evidence').forEach(button=>button.addEventListener('click',()=>{const ids=button.dataset.ids.split(','),sources=Object.fromEntries(ids.filter(id=>state.sources[id]).map(id=>[id,state.sources[id]]));openSources(null,sources)}))}

