function openChart(metric){const rows=state.metrics.series[metric]||[],label=FUEL[metric]||metric.replaceAll('_',' '),p=latest(rows);const modal=$('#chart-modal');$('#modal-content').innerHTML=`<span class="kicker">${state.hours}-HOUR DETAIL</span><h2>${label}</h2><div class="chart-value">${p?number(p.value,p.unit):'—'}</div><p class="chart-meta">Move across the chart to inspect exact observations. The horizontal axis always represents the full selected window.</p>${detailedChart(rows,FUEL[metric]?COLORS[Object.keys(FUEL).indexOf(metric)]:COLORS[0])}<div class="chart-tooltip" id="chart-tooltip">${p?`${localTime(p.ts,true)} · ${number(p.value,p.unit)}`:'No data'}</div>`;modal.showModal();const svg=$('.modal-chart');if(svg&&rows.length)svg.addEventListener('pointermove',event=>{const rect=svg.getBoundingClientRect(),target=new Date(state.metrics.from).getTime()+Math.max(0,Math.min(1,(event.clientX-rect.left)/rect.width))*(new Date(state.metrics.to)-new Date(state.metrics.from)),x=rows.reduce((best,row)=>Math.abs(new Date(row.ts)-target)<Math.abs(new Date(best.ts)-target)?row:best,rows[0]);$('#chart-tooltip').textContent=`${localTime(x.ts,true)} · ${number(x.value,x.unit)} · ${x.source}`})}
