function citationMarkupWith(text,sources){const cited=new Set(),clean=readableTimes(text).replace(/[ \t]*\[(?:cite|calc):([-A-Za-z0-9_.:+]+)\][ \t]*/g,(_,id)=>{if(sources[id])cited.add(id);return ' '}).replace(/[ \t]+([,.;:!?])/g,'$1').replace(/[ \t]{2,}/g,' ').trim();return {text:escapeHtml(clean).replace(/\n/g,'<br>'),count:cited.size}}

